# ==============================================================================# 028_NOTIFICATION_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS notifications(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    title TEXT,    message TEXT,    level TEXT,    status TEXT)""")conn.commit()def notify(title, message, level="INFO"):    cur.execute(        """        INSERT INTO notifications(            timestamp,            title,            message,            level,            status        )        VALUES(?,?,?,?,?)        """,        (            datetime.now().isoformat(),            title,            message,            level,            "UNREAD"        )    )    conn.commit()notify(    "Mission Control",    "Sistema iniciado com sucesso.",    "SUCCESS")cur.execute("""SELECTid,title,level,statusFROM notificationsORDER BY id DESCLIMIT 10""")print("="*80)print("NOTIFICATION ENGINE")print("="*80)for row in cur.fetchall():    print(dict(row))print("="*80)conn.close()

